INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9631,1,101,'名解',2,'理解','名词解释：阴阳',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9631,'名解','阴阳是中国古代哲学的一对范畴，是对自然界相互关联的某些事物或现象对立双方属性的概括。凡是运动的、外向的、上升的、温热的、明亮的都属于阳；静止的、内守的、下降的、寒冷的、晦暗的都属于阴。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9631,101);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9632,1,102,'名解',2,'理解','名词解释：五行',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9632,'名解','五行即木、火、土、金、水五种物质及其运动变化，中医学用以说明人体的生理病理及自然界万物的相互联系。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9632,102);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9633,1,103,'名解',3,'理解','名词解释：藏象',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9633,'名解','藏象指藏于体内的内脏及其表现于外的生理病理征象及脏腑之间、脏腑与形体官窍之间的联系。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9633,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9634,1,103,'名解',2,'理解','名词解释：脏与腑',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9634,'名解','五脏指心、肝、脾、肺、肾，其功能特点是化生和贮藏精气；六腑指胆、胃、小肠、大肠、膀胱、三焦，其功能特点是受盛和传化水谷。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9634,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9635,1,104,'名解',2,'理解','名词解释：气',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9635,'名解','气是构成人体和维持人体生命活动的最基本物质，具有推动、温煦、防御、固摄、气化等作用。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9635,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9636,1,104,'名解',3,'理解','名词解释：元气',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9636,'名解','元气又称原气，由肾中精气所化生，是人体生命活动的原动力。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9636,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9637,1,104,'名解',3,'理解','名词解释：宗气',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9637,'名解','宗气由肺吸入的清气与脾胃运化的水谷精气结合而成，聚于胸中，贯心脉而司呼吸。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9637,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9638,1,104,'名解',3,'理解','名词解释：卫气',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9638,'名解','卫气行于脉外，具有护卫肌表、抵御外邪、温养脏腑、调节腠理开合的作用。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9638,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9639,1,104,'名解',3,'理解','名词解释：营气',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9639,'名解','营气行于脉中，化生血液，营养全身。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9639,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9640,1,104,'名解',2,'理解','名词解释：血液',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9640,'名解','血是循行于脉中的富有营养的红色液态物质，是构成人体和维持生命活动的基本物质之一。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9640,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9641,1,104,'名解',2,'理解','名词解释：津液',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9641,'名解','津液是人体一切正常水液的总称，包括各脏腑组织器官的内在体液及其正常的分泌物。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9641,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9642,1,105,'名解',2,'理解','名词解释：经络',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9642,'名解','经络是运行气血、联系脏腑肢节、沟通上下内外的通路，包括经脉和络脉。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9642,105);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9643,1,105,'名解',2,'理解','名词解释：十二经脉',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9643,'名解','十二经脉是手三阴、手三阳、足三阴、足三阳的总称，是经络系统的主体。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9643,105);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9644,1,105,'名解',3,'理解','名词解释：奇经八脉',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9644,'名解','奇经八脉是督脉、任脉、冲脉、带脉、阴跷脉、阳跷脉、阴维脉、阳维脉的总称，具有调节十二经气血的作用。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9644,105);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9645,1,106,'名解',2,'理解','名词解释：六淫',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9645,'名解','六淫即风、寒、暑、湿、燥、火六种外感病邪的统称。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9645,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9646,1,106,'名解',2,'理解','名词解释：七情',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9646,'名解','七情即喜、怒、忧、思、悲、恐、惊七种情志活动，是引起内伤病的主要因素之一。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9646,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9647,1,106,'名解',3,'理解','名词解释：痰饮',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9647,'名解','痰饮是机体水液代谢障碍所形成的病理产物，稠浊者为痰，清稀者为饮。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9647,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9648,1,106,'名解',3,'理解','名词解释：瘀血',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9648,'名解','瘀血是血液运行不畅或离经之血积存体内的病理产物，既是病理产物又是致病因素。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9648,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9649,1,107,'名解',3,'理解','名词解释：正邪相争',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9649,'名解','正邪相争是正气与邪气相互交争的病理过程，决定发病与病机的虚实变化。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9649,107);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9650,1,107,'名解',3,'理解','名词解释：阴阳失调',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9650,'名解','阴阳失调是机体阴阳失去相对平衡而出现偏盛偏衰的病理变化。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9650,107);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9651,2,201,'名解',2,'理解','名词解释：望诊',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9651,'名解','望诊是医生运用视觉观察病人的神、色、形、态及舌象等以诊察病情的方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9651,201);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9652,2,201,'名解',3,'理解','名词解释：望神',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9652,'名解','望神是观察病人神气的盛衰有无，以判断病情轻重和预后吉凶。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9652,201);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9653,2,209,'名解',2,'理解','名词解释：舌诊',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9653,'名解','舌诊是观察舌质与舌苔的变化以诊察脏腑气血阴阳虚实的方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9653,209);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9654,2,204,'名解',2,'理解','名词解释：脉诊',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9654,'名解','脉诊是医生用手指触按病人的脉搏，借以体察脉象变化，推断病情的诊察方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9654,204);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9655,2,203,'名解',3,'理解','名词解释：十问歌',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9655,'名解','十问歌概括问诊的要点，即问寒热、问汗、问头身、问便、问饮食、问胸腹、问聋、问渴、问旧病、问因。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9655,203);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9656,2,205,'名解',3,'理解','名词解释：八纲辨证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9656,'名解','八纲辨证是以阴、阳、表、里、寒、热、虚、实八类证候为纲，分析归纳病情的辨证方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9656,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9657,2,205,'名解',3,'理解','名词解释：表证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9657,'名解','表证是外邪侵袭肌表所致的证候，以恶寒发热、头身疼痛、脉浮为特征。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9657,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9658,2,205,'名解',3,'理解','名词解释：里证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9658,'名解','里证是病位深在于里（脏腑、气血、骨髓）的一类证候。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9658,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9659,2,205,'名解',3,'理解','名词解释：虚证与实证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9659,'名解','虚证是正气不足、机体抗病能力减弱所致的证候；实证是邪气亢盛、正邪交争剧烈所致的证候。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9659,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9660,2,206,'名解',3,'理解','名词解释：脏腑辨证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9660,'名解','脏腑辨证是根据脏腑的生理功能与病理表现，对疾病进行定位定性分析的辨证方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9660,206);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9661,2,208,'名解',4,'理解','名词解释：卫气营血辨证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9661,'名解','卫气营血辨证是温病学中用于分析温病病位深浅、病情轻重、传变规律的辨证方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9661,208);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9662,3,320,'名解',2,'理解','名词解释：四气',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9662,'名解','四气即寒、热、温、凉四种药性，反映药物影响人体阴阳寒热的作用性质。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9662,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9663,3,320,'名解',2,'理解','名词解释：五味',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9663,'名解','五味即辛、甘、酸、苦、咸五种药味，用以概括药物的功效。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9663,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9664,3,320,'名解',3,'理解','名词解释：归经',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9664,'名解','归经是药物对机体某部分（脏腑或经络）的选择性作用，是药物作用部位的定位概念。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9664,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9665,3,320,'名解',3,'理解','名词解释：升降浮沉',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9665,'名解','升降浮沉是指药物作用的趋向性，升是上升、降是下降、浮是发散、沉是泄利。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9665,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9666,3,320,'名解',3,'理解','名词解释：君臣佐使',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9666,'名解','君臣佐使是方剂配伍的基本结构，君药是方中针对主病或主证起主要治疗作用的药物。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9666,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9667,3,320,'名解',3,'理解','名词解释：十八反',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9667,'名解','十八反是中药配伍禁忌，如甘草反甘遂、大戟、海藻、芫花；乌头反半夏、瓜蒌、贝母、白蔹、白及等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9667,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9668,3,320,'名解',4,'理解','名词解释：十九畏',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9668,'名解','十九畏是中药配伍禁忌，如硫黄畏朴硝、水银畏砒霜、狼毒畏密陀僧等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9668,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9669,3,320,'名解',2,'理解','名词解释：道地药材',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9669,'名解','道地药材是指特定产区的优质药材，如四川的黄连、云南的三七等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9669,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9670,4,419,'名解',2,'理解','名词解释：方剂',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9670,'名解','方剂是在辨证审因、确定治法之后，选择合适的药物，酌定用量，按组方原则配伍而成的药物组合。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9670,419);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9671,4,419,'名解',2,'理解','名词解释：八法',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9671,'名解','八法即汗、吐、下、和、温、清、消、补八种治疗大法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9671,419);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9672,4,419,'名解',2,'理解','名词解释：煎服法',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9672,'名解','煎服法是指汤剂的煎煮方法（如先煎、后下、包煎、烊化）及服药方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9672,419);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9673,4,419,'名解',2,'理解','名词解释：成方',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9673,'名解','成方是经过长期临床验证、配伍固定的定型方剂。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9673,419);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9674,5,516,'名解',2,'理解','名词解释：腧穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9674,'名解','腧穴是人体脏腑经络之气输注于体表的特殊部位，既是疾病的反应点又是针灸治疗的刺激点。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9674,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9675,5,516,'名解',3,'理解','名词解释：特定穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9675,'名解','特定穴是十四经中具有特定名称、特殊治疗作用的腧穴，包括五输穴、原穴、络穴、郄穴、募穴、背俞穴等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9675,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9676,5,516,'名解',3,'理解','名词解释：五输穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9676,'名解','五输穴是十二经脉分布在肘膝关节以下的井、荥、输、经、合五类腧穴的总称。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9676,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9677,5,516,'名解',3,'理解','名词解释：八会穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9677,'名解','八会穴是脏、腑、气、血、筋、脉、骨、髓八者精气会聚的腧穴。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9677,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9678,5,516,'名解',3,'理解','名词解释：原穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9678,'名解','原穴是脏腑原气输注、经过和留止于十二经脉的腧穴。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9678,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9679,5,516,'名解',3,'理解','名词解释：络穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9679,'名解','络穴是络脉从本经别出的穴位，具有沟通表里两经的作用。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9679,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9680,5,516,'名解',3,'理解','名词解释：背俞穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9680,'名解','背俞穴是脏腑之气输注于背腰部的腧穴，位于膀胱经第一侧线。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9680,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9681,5,516,'名解',3,'理解','名词解释：募穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9681,'名解','募穴是脏腑之气汇聚于胸腹部的腧穴。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9681,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9682,5,516,'名解',3,'理解','名词解释：郄穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9682,'名解','郄穴是经脉气血深聚之处的穴位，多用于治疗急性病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9682,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9683,5,516,'名解',3,'理解','名词解释：下合穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9683,'名解','下合穴是六腑之气下合于下肢足三阳经的腧穴，主治六腑病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9683,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9684,5,516,'名解',2,'理解','名词解释：阿是穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9684,'名解','阿是穴是以压痛或其他反应点作为取穴依据的腧穴，无固定位置与名称。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9684,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9685,5,516,'名解',2,'理解','名词解释：奇穴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9685,'名解','奇穴又称经外奇穴，是既有一定名称、位置，又有明确主治，但未归入十四经的腧穴。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9685,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9686,5,516,'名解',3,'理解','名词解释：得气',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9686,'名解','得气是针刺时医生手下有沉紧感，病人有酸麻胀重等感应，是针刺取得疗效的关键。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9686,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9687,6,608,'名解',3,'理解','名词解释：辨证论治',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9687,'名解','辨证论治是中医认识疾病和治疗疾病的基本原则，包括辨证和论治两个过程。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9687,608);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9688,6,608,'名解',3,'理解','名词解释：同病异治',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9688,'名解','同病异治是指同一种疾病，由于病机不同，采用不同治法的治疗原则。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9688,608);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9689,6,608,'名解',3,'理解','名词解释：异病同治',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9689,'名解','异病同治是指不同的疾病，由于病机相同，采用相同治法的治疗原则。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9689,608);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9690,6,608,'名解',3,'理解','名词解释：证候',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9690,'名解','证候是疾病过程中某一阶段的病因、病位、病性、邪正关系的概括。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9690,608);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9691,6,601,'名解',2,'理解','名词解释：咳嗽',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9691,'名解','咳嗽是指肺失宣降，肺气上逆，发出咳声或咯吐痰液的病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9691,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9692,6,601,'名解',3,'理解','名词解释：哮病',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9692,'名解','哮病是一种发作性的痰鸣气喘疾病，以喉中哮鸣有声、呼吸气促困难为特征。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9692,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9693,6,601,'名解',3,'理解','名词解释：喘证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9693,'名解','喘证以呼吸困难、张口抬肩、鼻翼扇动、不能平卧为特征，甚则摇身撷肚。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9693,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9694,6,602,'名解',2,'理解','名词解释：心悸',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9694,'名解','心悸是指病人自觉心中悸动、惊惕不安，甚则不能自主的一种病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9694,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9695,6,602,'名解',3,'理解','名词解释：胸痹',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9695,'名解','胸痹是以胸部闷痛，甚则胸痛彻背、喘息不得卧为主症的病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9695,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9696,6,603,'名解',2,'理解','名词解释：胃痛',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9696,'名解','胃痛又称胃脘痛，是以胃脘部疼痛为主症的病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9696,603);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9697,6,603,'名解',2,'理解','名词解释：泄泻',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9697,'名解','泄泻以排便次数增多、粪质稀溏或完谷不化、甚至泻出如水样为主症。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9697,603);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9698,6,603,'名解',3,'理解','名词解释：痢疾',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9698,'名解','痢疾以腹痛、里急后重、下痢赤白脓血为主症。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9698,603);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9699,6,604,'名解',2,'理解','名词解释：黄疸',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9699,'名解','黄疸以目黄、身黄、小便黄为主症，其中目睛黄染尤为特征。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9699,604);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9700,6,604,'名解',3,'理解','名词解释：鼓胀',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9700,'名解','鼓胀是以腹部胀大如鼓、皮色苍黄、脉络暴露为主症的病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9700,604);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9701,6,602,'名解',2,'理解','名词解释：不寐',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9701,'名解','不寐是以经常不能获得正常睡眠为特征的一类病证，轻者入睡困难，重者彻夜不眠。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9701,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9702,6,605,'名解',2,'理解','名词解释：水肿',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9702,'名解','水肿是以头面、眼睑、四肢、腹背甚至全身浮肿为特征的一类病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9702,605);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9703,6,605,'名解',2,'理解','名词解释：淋证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9703,'名解','淋证以小便频数短涩、淋沥刺痛、小腹拘急引痛为主症。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9703,605);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9704,6,605,'名解',3,'理解','名词解释：癃闭',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9704,'名解','癃闭以小便量少、排尿困难，甚至小便闭塞不通为主症。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9704,605);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9705,6,606,'名解',2,'理解','名词解释：消渴',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9705,'名解','消渴以多饮、多食、多尿、形体消瘦为主症，相当于糖尿病。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9705,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9706,6,606,'名解',2,'理解','名词解释：血证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9706,'名解','凡血液不循常道，上溢于口鼻诸窍，下出于前后二阴，或渗出肌肤之外的病证，统称血证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9706,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9707,6,606,'名解',3,'理解','名词解释：虚劳',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9707,'名解','虚劳是以脏腑亏损、气血阴阳不足、久虚不复成劳为主要病机的慢性衰弱性病证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9707,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9708,6,606,'名解',2,'理解','名词解释：郁证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9708,'名解','郁证以心情抑郁、情绪不宁、胸胁胀满疼痛、易哭善怒为主要表现。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9708,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9709,6,607,'名解',2,'理解','名词解释：痹证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9709,'名解','痹证以肢体关节肌肉疼痛、酸楚、重着、麻木、屈伸不利为主症。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9709,607);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9710,6,607,'名解',3,'理解','名词解释：痿证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9710,'名解','痿证以肢体筋脉弛缓、软弱无力、日久不能随意运动而致肌肉萎缩为主症。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9710,607);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9711,6,607,'名解',3,'理解','名词解释：痉证',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9711,'名解','痉证以项背强急、四肢抽搐、甚至角弓反张为主症。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9711,607);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9712,6,607,'名解',2,'理解','名词解释：腰痛',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9712,'名解','腰痛以腰部一侧或两侧疼痛为主症，可牵及下肢。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9712,607);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9713,6,602,'名解',2,'理解','名词解释：眩晕',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9713,'名解','眩晕是以头晕眼花为主症的病证，轻者闭目即止，重者如坐舟车。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9713,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9714,6,602,'名解',3,'理解','名词解释：中风',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9714,'名解','中风以猝然昏仆、不省人事、半身不遂、口眼歪斜为主症，亦有未见昏仆而仅见半身不遂者。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9714,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9715,2,202,'名解',2,'理解','名词解释：闻诊',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9715,'名解','闻诊包括听声音和嗅气味两方面，以判断病性。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9715,202);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9716,2,203,'名解',2,'理解','名词解释：问诊',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9716,'名解','问诊是医生通过询问病人及其家属以了解病情、病史的一种诊察方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9716,203);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9717,1,108,'名解',2,'理解','名词解释：治未病',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9717,'名解','治未病包括未病先防、既病防变、瘥后防复，是中医预防思想的核心。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9717,108);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9718,1,108,'名解',3,'理解','名词解释：扶正祛邪',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9718,'名解','扶正祛邪是运用补益或攻泻的方法，调整正邪关系以恢复健康的基本原则。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9718,108);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9719,1,108,'名解',3,'理解','名词解释：三因制宜',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9719,'名解','三因制宜即因时、因地、因人制宜，根据季节、地域、个体差异制定适宜的治疗方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9719,108);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9720,1,108,'名解',3,'理解','名词解释：标本缓急',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9720,'名解','标本缓急是指根据病证标本主次、缓急轻重确定治疗次序的原则。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9720,108);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9721,1,103,'名解',3,'理解','名词解释：肝主疏泄',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9721,'名解','肝主疏泄是指肝具有疏通、畅达全身气机，促进气血运行、脾胃运化、情志调畅等功能。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9721,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9722,1,103,'名解',3,'理解','名词解释：脾主运化',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9722,'名解','脾主运化是指脾具有把水谷化为精微并转输至全身的功能。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9722,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9723,1,103,'名解',3,'理解','名词解释：肾主水',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9723,'名解','肾主水是指肾具有主持和调节全身水液代谢的功能。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9723,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9724,1,103,'名解',3,'理解','名词解释：肺朝百脉',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9724,'名解','肺朝百脉是指全身的血液都通过百脉会聚于肺，经肺的呼吸进行气体交换。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9724,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9725,1,103,'名解',2,'理解','名词解释：心主血脉',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9725,'名解','心主血脉是指心气推动血液在脉中运行，濡养全身。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9725,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9726,1,103,'名解',2,'理解','名词解释：脾胃为气血生化之源',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9726,'名解','脾胃运化水谷精微，化生气血以濡养全身，故为气血生化之源。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9726,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9727,3,320,'名解',3,'理解','名词解释：引经药',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9727,'名解','引经药是指能引导诸药直达病所的药物，如太阳经头痛用羌活。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9727,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9728,3,320,'名解',3,'理解','名词解释：相须相使',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9728,'名解','相须是功效相似的药物合用增强疗效；相使是一药为主、一药为辅，辅药增强主药功效。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9728,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9729,3,320,'名解',4,'理解','名词解释：相畏相杀',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9729,'名解','相畏是一种药物的毒性反应被另一种药物减轻或消除；相杀是一种药物能减轻或消除另一种药物的毒性。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9729,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9730,3,320,'名解',4,'理解','名词解释：相恶',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9730,'名解','相恶是一种药物的某些功效被另一种药物削弱或消除。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9730,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9731,3,320,'名解',4,'理解','名词解释：相反',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9731,'名解','相反是两种药物合用能产生毒性反应或增强毒性反应，属于配伍禁忌。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9731,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9732,5,516,'名解',2,'理解','名词解释：针法',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9732,'名解','针法是用毫针刺入腧穴，通过手法操作以防治疾病的方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9732,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9733,5,516,'名解',2,'理解','名词解释：灸法',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9733,'名解','灸法是以艾绒为主要材料，点燃后熏灼体表腧穴以防治疾病的方法。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9733,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9734,6,608,'名解',2,'理解','名词解释：治未病（内科）',5.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9734,'名解','在内科学中治未病强调未病先防、既病防变、已病早治，防止疾病传变发展。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9734,608);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9735,1,101,'简答',3,'理解','简答题：简述阴阳学说在中医学中的应用。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9735,'简答','（1）说明人体的组织结构，上为阳、下为阴，背为阳、腹为阴，六腑为阳、五脏为阴；（2）说明人体的生理功能，如''阴平阳秘，精神乃治''；（3）说明人体的病理变化，阴阳偏盛偏衰；（4）指导疾病的诊断，如善诊者先别阴阳；（5）指导疾病的防治，调和阴阳。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9735,101);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9736,1,102,'简答',3,'理解','简答题：简述五行相生相克的关系。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9736,'简答','五行相生：木生火、火生土、土生金、金生水、水生木；相克：木克土、土克水、水克火、火克金、金克木。相生是滋生助长，相克是制约抑制，两者相互为用，维持五行系统的动态平衡。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9736,102);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9737,1,102,'简答',4,'理解','简答题：简述五行学说在中医学中的应用。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9737,'简答','（1）说明五脏的生理特性及脏腑间的相互资生与制约关系；（2）说明五脏病变的相互传变（相生传变与相克传变）；（3）用于疾病的诊断，从色脉结合推断病位；（4）用于疾病的治疗，如滋水涵木、培土生金、扶土抑木、泻南补北等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9737,102);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9738,1,103,'简答',3,'理解','简答题：简述肝主疏泄的生理功能。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9738,'简答','（1）调畅气机；（2）促进脾胃的运化功能；（3）调畅情志；（4）促进血液与津液的运行输布；（5）调节生殖功能（疏泄与藏血协调）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9738,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9739,1,103,'简答',3,'理解','简答题：简述肺主气司呼吸的功能。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9739,'简答','肺主呼吸之气，是肺主一身之气的基础；肺主一身之气体现在：一是参与气的生成，特别是宗气的生成，二是调节全身气机。肺吸入清气与脾胃水谷精气结合成宗气，贯心脉行呼吸。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9739,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9740,1,103,'简答',3,'理解','简答题：简述脾主运化的功能及意义。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9740,'简答','脾主运化包括运化水谷精微和运化水液两方面。运化水谷精微指脾把水谷化为精微并转输全身，为气血生化之源，故脾为后天之本；运化水液指脾对水液的吸收、转输和布散。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9740,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9741,1,103,'简答',3,'理解','简答题：简述肾的生理功能。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9741,'简答','（1）藏精，主生长发育与生殖，为先天之本；（2）主水，主持调节水液代谢；（3）主纳气，摄纳肺吸入之清气；（4）主骨生髓，其华在发；（5）开窍于耳及二阴。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9741,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9742,1,103,'简答',3,'理解','简答题：简述心与肺在生理上的联系。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9742,'简答','心主血，肺主气。心与肺的关系主要体现在气血相互为用：肺气助心行血，心主血脉促进肺的呼吸。宗气贯心脉而司呼吸，是联系心肺的枢纽。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9742,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9743,1,103,'简答',3,'理解','简答题：简述肝与脾在生理病理上的联系。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9743,'简答','生理上，肝主疏泄促进脾运化，脾运化水谷精微以养肝；病理上，肝失疏泄可致脾失健运（木乘土），脾虚亦可导致肝失疏泄。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9743,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9744,1,103,'简答',3,'理解','简答题：简述肺与肾在生理上的联系。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9744,'简答','（1）呼吸方面：肺主呼气、肾主纳气，共同维持呼吸深度；（2）水液方面：肺为水之上源，肾为主水之脏，共同调节水液代谢；（3）阴液相互资生，金水相生。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9744,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9745,1,104,'简答',3,'理解','简答题：简述气与血的关系。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9745,'简答','气为血之帅：气能生血、气能行血、气能摄血；血为气之母：血能载气、血能养气。临床常见气滞血瘀、气虚血瘀、气随血脱等证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9745,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9746,1,104,'简答',2,'理解','简答题：简述气的生理功能。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9746,'简答','（1）推动作用；（2）温煦作用；（3）防御作用；（4）固摄作用；（5）气化作用；（6）营养作用。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9746,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9747,1,104,'简答',3,'理解','简答题：简述血液的正常运行依赖哪些因素。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9747,'简答','（1）心气的推动；（2）肺朝百脉、肺气的宣降；（3）肝主疏泄、藏血；（4）脾主统血；（5）脉道通畅及血液充盈。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9747,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9748,1,105,'简答',3,'理解','简答题：简述十二经脉的走向规律。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9748,'简答','手三阴经从胸走手，手三阳经从手走头，足三阳经从头走足，足三阴经从足走腹（胸）。阴升阳降，形成循环。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9748,105);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9749,1,105,'简答',2,'理解','简答题：简述经络的生理功能。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9749,'简答','（1）沟通表里上下，联系脏腑器官；（2）运行气血，濡养全身；（3）感应传导作用；（4）调节机能平衡。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9749,105);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9750,1,106,'简答',3,'理解','简答题：简述六淫致病的共同特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9750,'简答','（1）外感性，多从肌表、口鼻入侵；（2）季节性；（3）地域性；（4）相兼性，常两种以上合邪；（5）转化性。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9750,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9751,1,106,'简答',3,'理解','简答题：简述风邪的性质和致病特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9751,'简答','（1）风为阳邪，其性开泄，易袭阳位；（2）风性善行而数变；（3）风为百病之长。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9751,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9752,1,106,'简答',3,'理解','简答题：简述湿邪的性质和致病特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9752,'简答','（1）湿为阴邪，易阻遏气机，损伤阳气；（2）湿性重浊；（3）湿性黏滞；（4）湿性趋下，易袭阴位。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9752,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9753,1,106,'简答',3,'理解','简答题：简述寒邪的性质和致病特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9753,'简答','（1）寒为阴邪，易伤阳气；（2）寒性凝滞，主痛；（3）寒性收引，易致经脉拘急、气机收敛。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9753,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9754,1,106,'简答',3,'理解','简答题：简述七情致病的特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9754,'简答','（1）直接伤及内脏（怒伤肝、喜伤心、思伤脾、忧悲伤肺、恐伤肾）；（2）影响脏腑气机（怒则气上、喜则气缓、思则气结、悲则气消、恐则气下、惊则气乱）；（3）情志波动可使病情加重或恶化。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9754,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9755,1,106,'简答',4,'理解','简答题：简述痰饮的致病特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9755,'简答','（1）阻滞气机，阻碍气血运行；（2）致病广泛，变化多端，''百病多由痰作祟''；（3）病势缠绵，病程较长；（4）易蒙蔽清窍，扰乱心神。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9755,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9756,1,107,'简答',4,'理解','简答题：简述邪正盛衰与虚实变化的关系。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9756,'简答','邪正盛衰决定病机虚实：正盛邪退则病退；邪盛正衰则病进。虚指正气不足，实指邪气亢盛。虚实夹杂、虚实转化（由实转虚、因虚致实）是常见病理变化。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9756,107);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9757,2,201,'简答',3,'理解','简答题：简述望神的临床意义。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9757,'简答','得神者昌，失神者亡。得神提示精气充盛、预后良好；少神提示正气不足；失神提示精气大亏、病情危重；假神为垂危病人出现的精神暂时好转的假象。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9757,201);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9758,2,201,'简答',2,'理解','简答题：简述望面色时五色主病。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9758,'简答','青色主寒证、痛证、瘀血、惊风；赤色主热证；黄色主脾虚、湿证；白色主虚证、寒证、失血；黑色主肾虚、寒证、水饮、瘀血。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9758,201);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9759,2,209,'简答',3,'理解','简答题：简述望舌质与舌苔的主要内容。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9759,'简答','舌质包括舌色（淡红、淡白、红、绛、紫）、舌形（老嫩、胖瘦、点刺、裂纹）与舌态（强硬、痿软、歪斜等）；舌苔包括苔色（白、黄、灰、黑）与苔质（厚薄、润燥、腻腐、剥落等）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9759,209);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9760,2,204,'简答',3,'理解','简答题：简述寸口脉诊的脏腑分配。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9760,'简答','左寸候心，左关候肝，左尺候肾；右寸候肺，右关候脾胃，右尺候命门。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9760,204);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9761,2,204,'简答',2,'理解','简答题：简述浮脉、沉脉、数脉、迟脉的主病。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9761,'简答','浮脉主表证；沉脉主里证；数脉主热证；迟脉主寒证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9761,204);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9762,2,205,'简答',3,'理解','简答题：简述表证与里证的区别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9762,'简答','表证病程短，恶寒发热并见，舌苔薄白，脉浮，多由外邪侵袭所致；里证病程长，寒热单见，舌苔可厚腻或舌质变化明显，脉沉，病位在脏腑。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9762,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9763,2,205,'简答',3,'理解','简答题：简述寒证与热证的鉴别要点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9763,'简答','从寒热喜恶（恶寒喜暖为寒，恶热喜冷为热）、口渴饮冷与否、面色（白为寒、赤为热）、二便（清稀为寒、黄赤为热）、舌脉（舌淡苔白脉迟为寒，舌红苔黄脉数为热）等方面鉴别。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9763,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9764,2,205,'简答',3,'理解','简答题：简述虚证与实证的鉴别要点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9764,'简答','虚证病程长、起病缓、体质弱，以不足为特征（气虚乏力、血虚面白等）；实证病程短、起病急、体质较实，以亢盛为特征（壮热、声高气粗、腹痛拒按等）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9764,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9765,2,205,'简答',4,'理解','简答题：简述亡阳与亡阴的鉴别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9765,'简答','亡阳：面色苍白、四肢厥冷、冷汗淋漓、气息微弱、脉微欲绝；亡阴：汗热而粘、身热烦渴、皮肤皱瘪、脉细数疾。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9765,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9766,2,206,'简答',3,'理解','简答题：简述心气虚证与心阳虚证的区别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9766,'简答','心气虚以心悸胸闷、气短乏力、动则加剧为特点；心阳虚在气虚基础上兼见畏寒肢冷、面色㿠白、脉迟等阳虚寒象。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9766,206);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9767,2,206,'简答',3,'理解','简答题：简述肝气郁结证的主要表现。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9767,'简答','情志抑郁、善太息、胸胁或少腹胀痛、窜痛，妇女可见乳房胀痛、月经不调，舌淡红苔薄白、脉弦。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9767,206);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9768,2,206,'简答',3,'理解','简答题：简述脾不统血证的表现。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9768,'简答','在脾气虚（食少便溏、气短乏力）基础上出现各种出血，如便血、尿血、肌衄、崩漏等，血色淡红。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9768,206);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9769,3,320,'简答',3,'理解','简答题：简述中药四气五味对临床用药的意义。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9769,'简答','四气反映药物寒热温凉之性，用于调整机体阴阳盛衰；五味反映药物功效趋向，辛散、甘补、酸收、苦泄、咸软。临床根据证候寒热虚实选药配伍。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9769,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9770,3,320,'简答',3,'理解','简答题：简述解表药的使用注意事项。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9770,'简答','（1）发汗以微汗为度，不可过汗；（2）表虚自汗、阴虚盗汗慎用；（3）久病体虚、气虚外感应配伍补益药；（4）入汤剂不宜久煎。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9770,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9771,3,320,'简答',4,'理解','简答题：简述麻黄与桂枝功效的异同。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9771,'简答','相同：均能发汗解表，治疗风寒表证。不同：麻黄发汗力强，兼宣肺平喘、利水消肿，适用于表实无汗之证；桂枝发汗力弱，长于温通经脉、助阳化气，适用于表虚自汗及寒凝血滞诸证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9771,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9772,3,320,'简答',4,'理解','简答题：简述石膏与知母功效的异同。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9772,'简答','相同：均清热泻火，除烦止渴，治气分实热。不同：石膏偏入肺胃，清泻肺胃实火，煅用敛疮；知母质润，善滋阴润燥，能清下焦相火。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9772,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9773,3,320,'简答',4,'理解','简答题：简述黄芩、黄连、黄柏三药功效的同与异。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9773,'简答','相同：均苦寒清热燥湿、泻火解毒。不同：黄芩清上焦肺热为主，兼止血安胎；黄连清中焦心胃之火、湿热痞痢为主；黄柏清下焦湿热，泻肾经相火，退虚热。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9773,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9774,3,320,'简答',4,'理解','简答题：简述人参、黄芪功效的异同。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9774,'简答','相同：均能补气，治气虚诸证。不同：人参大补元气、复脉固脱、生津安神，善治气虚欲脱重证；黄芪补气升阳、固表止汗、利水消肿、托毒生肌，善治中气下陷、表虚自汗。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9774,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9775,3,320,'简答',3,'理解','简答题：简述地黄有生熟之异及其临床应用。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9775,'简答','鲜地黄/生地黄性寒，长于清热凉血、养阴生津，治热入营血；熟地黄性微温，长于补血养阴、填精益髓，治血虚、肝肾阴虚。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9775,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9776,3,320,'简答',4,'理解','简答题：简述十八反的内容。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9776,'简答','甘草反甘遂、大戟、海藻、芫花；乌头（川乌、草乌）反半夏、瓜蒌、贝母、白蔹、白及；藜芦反人参、沙参、丹参、玄参、细辛、芍药。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9776,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9777,4,419,'简答',3,'理解','简答题：简述方剂中君臣佐使的配伍意义。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9777,'简答','君药针对主病主证起主要治疗作用；臣药辅助君药加强治疗作用或治疗兼证；佐药制约君药毒性、佐助君药、治疗次要兼证；使药起调和诸药或引经作用。君臣佐使有序配伍，增效减毒。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9777,419);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9778,4,419,'简答',2,'理解','简答题：简述八法的具体内容。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9778,'简答','汗法（发汗解表）、吐法（涌吐）、下法（泻下）、和法（和解）、温法（温里）、清法（清热）、消法（消导）、补法（补益）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9778,419);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9779,4,401,'简答',4,'理解','简答题：简述麻黄汤与桂枝汤主治证的区别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9779,'简答','麻黄汤治外感风寒表实证，恶寒发热、无汗而喘、脉浮紧；桂枝汤治外感风寒表虚证，恶风发热、汗出、脉浮缓。两方证以有汗无汗、脉紧缓为辨。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9779,401);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9780,4,404,'简答',3,'理解','简答题：简述白虎汤的组成、功效与主治。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9780,'简答','组成：石膏、知母、甘草、粳米。功效：清热生津。主治：气分热盛证，症见壮热面赤、烦渴引饮、汗出恶热、脉洪大有力。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9780,404);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9781,4,406,'简答',4,'理解','简答题：简述六味地黄丸的组成及配伍特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9781,'简答','组成：熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓。配伍特点：三补三泻，以补为主——熟地补肾、山茱萸补肝、山药补脾，泽泻泻肾浊、丹皮泻肝火、茯苓渗脾湿。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9781,406);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9782,4,411,'简答',4,'理解','简答题：简述血府逐瘀汤的组成与主治。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9782,'简答','组成：桃仁、红花、当归、生地、川芎、赤芍、牛膝、桔梗、柴胡、枳壳、甘草。功效：活血化瘀、行气止痛。主治：胸中血瘀证，胸痛头痛日久、痛如针刺而有定处。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9782,411);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9783,4,414,'简答',3,'理解','简答题：简述茵陈蒿汤的组成、功效与主治。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9783,'简答','组成：茵陈、栀子、大黄。功效：清热利湿退黄。主治：湿热黄疸，一身面目俱黄、黄色鲜明、小便不利、腹微满。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9783,414);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9784,4,401,'简答',4,'理解','简答题：简述银翘散的功效主治及配伍特点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9784,'简答','功效：辛凉透表、清热解毒。主治：温病初起，发热微恶风寒、咽痛口渴。配伍特点：辛凉为主，配少量辛温（荆芥穗、淡豆豉）以助透邪，配芦根、竹叶清热生津，所谓''治上焦如羽，非轻不举''。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9784,401);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9785,5,516,'简答',3,'理解','简答题：简述针刺的注意事项。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9785,'简答','（1）针刺前检查针具，严格消毒；（2）避开血管，胸背肋间等部位注意深度，防止气胸；（3）孕妇腹部、腰骶部及合谷、三阴交等穴禁针；（4）醉酒、过饥、过饱、大惊、大恐者不宜针刺。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9785,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9786,5,516,'简答',2,'理解','简答题：简述灸法的作用。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9786,'简答','（1）温经散寒；（2）扶阳固脱；（3）消瘀散结；（4）防病保健，如灸足三里、关元以强身。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9786,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9787,5,516,'简答',3,'理解','简答题：简述足三里穴的定位、主治及常用配伍。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9787,'简答','定位：犊鼻穴下3寸，胫骨前嵴外一横指处。主治：胃痛呕吐、腹胀泄泻、下肢痿痹、虚劳等。常配中脘、内关治胃痛；配关元、气海治虚劳；常灸保健。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9787,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9788,5,516,'简答',3,'理解','简答题：简述合谷穴的定位、主治。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9788,'简答','定位：手背第1、2掌骨之间，约平第2掌骨桡侧中点。主治：头痛、齿痛、目赤肿痛、咽喉肿痛、发热、滞产等，是治疗头面部疾患的要穴（面口合谷收）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9788,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9789,5,516,'简答',3,'理解','简答题：简述内关穴的定位、主治。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9789,'简答','定位：腕横纹上2寸，掌长肌腱与桡侧腕屈肌腱之间。主治：心痛心悸、胃痛呕吐、失眠眩晕、晕车晕船，为心包经络穴，通阴维脉。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9789,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9790,6,601,'简答',3,'理解','简答题：简述感冒的主要证型及代表方。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9790,'简答','（1）风寒感冒：荆防败毒散或荆防达表汤；（2）风热感冒：银翘散或葱豉桔梗汤；（3）暑湿感冒：新加香薷饮；（4）气虚感冒：参苏饮；（5）阴虚感冒：加减葳蕤汤。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9790,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9791,6,601,'简答',3,'理解','简答题：简述咳嗽外感与内伤的区别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9791,'简答','外感咳嗽起病急、病程短，多兼表证，实证居多，治宜宣肺散邪；内伤咳嗽起病缓、病程长，常反复发作，可虚实夹杂，治宜调理脏腑、扶正祛邪。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9791,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9792,6,602,'简答',4,'理解','简答题：简述胸痹的基本病机及治疗原则。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9792,'简答','基本病机为心脉痹阻，本虚标实——本虚为心气、心阳、心血、心阴不足，标实为寒凝、气滞、血瘀、痰浊阻痹心脉。治疗原则：补其不足、泻其有余，活血通络。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9792,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9793,6,603,'简答',3,'理解','简答题：简述胃痛的病机及辨治要点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9793,'简答','病机为胃气阻滞，胃失和降，不通则痛。辨治要点：辨虚实（实证痛急拒按，虚证痛缓喜按）、辨寒热（寒痛得温则减，热痛遇热加重）、辨气血（气滞窜痛，血瘀刺痛固定）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9793,603);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9794,6,603,'简答',3,'理解','简答题：简述泄泻与痢疾的鉴别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9794,'简答','泄泻以大便溏薄、次数增多为主症，多无脓血、无里急后重；痢疾以腹痛、里急后重、下利赤白脓血为主症。两者病位均在肠，但病机病证不同。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9794,603);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9795,6,604,'简答',3,'理解','简答题：简述黄疸阳黄与阴黄的鉴别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9795,'简答','阳黄：病程短，黄色鲜明如橘色，伴发热口渴、小便短赤、苔黄腻、脉滑数，属湿热；阴黄：病程长，黄色晦暗如烟熏，伴畏寒神疲、苔白腻、脉濡缓，属寒湿。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9795,604);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9796,6,605,'简答',3,'理解','简答题：简述水肿的治疗原则（阳水与阴水）。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9796,'简答','阳水以祛邪为主，发汗、利尿、攻逐；阴水以扶正为主，健脾、温肾。同时注意发汗、利尿不可过用，以免伤正。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9796,605);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9797,6,606,'简答',4,'理解','简答题：简述消渴的上、中、下三消及其治法。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9797,'简答','上消（肺热津伤）：多饮，治以清热润肺、生津止渴，方用消渴方；中消（胃热炽盛）：多食，治以清胃泻火、养阴增液，方用玉女煎；下消（肾阴亏虚）：多尿，治以滋阴固肾，方用六味地黄丸。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9797,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9798,6,606,'简答',4,'理解','简答题：简述血证的治疗原则。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9798,'简答','治疗血证宜治火、治气、治血：治火以清热泻火凉血，治气以益气摄血或理气行气，治血以止血化瘀养血。热证凉血止血，虚证补气摄血，瘀证祛瘀止血。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9798,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9799,6,607,'简答',4,'理解','简答题：简述痹证的辨证分型及代表方。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9799,'简答','（1）行痹（风胜）：防风汤；（2）痛痹（寒胜）：乌头汤；（3）着痹（湿胜）：薏苡仁汤；（4）热痹：白虎加桂枝汤；（5）尪痹（久痹）：独活寄生汤。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9799,607);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9800,6,602,'简答',4,'理解','简答题：简述中风中经络与中脏腑的区别。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9800,'简答','中经络：无神志改变，仅见半身不遂、口眼歪斜、言语不利；中脏腑：猝然昏仆、不省人事，伴半身不遂等。中脏腑又有闭证（牙关紧闭、两手握固）与脱证（目合口开、手撒肢冷）之分。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9800,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9801,6,606,'简答',3,'理解','简答题：简述郁证的治疗原则。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9801,'简答','理气开郁、调畅情志为基本治则。实证以疏肝理气为主，配合活血、化痰、清火；虚证以养心安神、滋养肝肾为主。注意防止病情反复。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9801,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9802,6,602,'简答',4,'理解','简答题：简述不寐的辨证要点及常用方。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9802,'简答','辨证要点：辨虚实——虚证多心血不足、阴虚火旺、心胆气虚、心脾两虚；实证多肝郁化火、痰热内扰。常用方：酸枣仁汤（肝血不足）、归脾汤（心脾两虚）、天王补心丹（阴虚火旺）、龙胆泻肝汤（肝郁化火）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9802,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9803,6,603,'简答',3,'理解','简答题：简述便秘的辨证治疗。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9803,'简答','分虚实：热秘麻子仁丸，气秘六磨汤，冷秘温脾汤，气虚秘黄芪汤，血虚秘润肠丸，阴虚秘增液汤。治疗以通下为主，但须据虚实标本调治。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9803,603);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9804,6,604,'简答',4,'理解','简答题：简述胁痛的辨证治疗要点。',10.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9804,'简答','病位在肝胆，实证以气滞、血瘀、湿热为主，分别用柴胡疏肝散、复元活血汤、龙胆泻肝汤；虚证以肝阴不足为主，用一贯煎滋补肝肾、柔肝止痛。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9804,604);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9805,1,101,'论述',4,'分析','论述题：试述阴阳学说在中医治疗学中的指导意义。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9805,'论述','阴阳学说认为疾病发生的根本原因是阴阳失调。治疗上：（1）确定治疗原则：阳盛则热，热者寒之；阴盛则寒，寒者热之；阳虚则寒，阳虚者扶阳抑阴；阴虚则热，阴虚者壮水制火。（2）阴阳偏盛者损其有余，阴阳偏衰者补其不足。（3）调整阴阳使其恢复''阴平阳秘''，是治疗疾病的根本目的。（4）阴阳学说还指导具体治法如壮水制火、益火消阴、引火归原等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9805,101);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9806,1,102,'论述',4,'分析','论述题：试述五行相生相克失常（乘侮）的病机及临床意义。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9806,'论述','五行生克失常包括相乘（克之太过）与相侮（反克）。肝木乘脾土（木乘土）可致肝脾不和；肺金乘肝木（金乘木）可致肝肺失调；脾土侮肝木（土侮木）即木虚土侮。临床运用：如肝木乘脾，治以抑木扶土（逍遥散）；肝火犯肺，木火刑金，治以清肝泻肺；水不涵木、肝阳上亢，治以滋水涵木。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9806,102);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9807,1,103,'论述',4,'分析','论述题：试述脾与胃在生理病理上的相互关系。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9807,'论述','脾与胃同居中焦，以膜相连。生理：（1）纳运相合：胃主受纳腐熟水谷，脾主运化转输；（2）升降相因：脾主升清，胃主降浊；（3）燥湿相济：脾喜燥恶湿，胃喜润恶燥。病理：脾失健运则胃纳呆滞，胃失和降则脾运受阻；脾升不足则清气下陷，胃降太过则浊气上逆（呕吐、泄泻并见）。治疗上常脾胃同治，如调理脾胃升降、燥湿相济。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9807,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9808,1,103,'论述',4,'分析','论述题：试述心、肝、脾三脏在血液生成和运行中的作用。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9808,'论述','血液的生成依赖脾的运化（后天之本、气血生化之源）和肝的疏泄藏血，以及肾精化血；血液的运行依赖心气推动、肺朝百脉、脾主统血、肝主藏血疏泄。若脾虚统摄无权则出血（脾不统血），肝失藏血则血溢脉外，心气不足则血行迟缓。临床从心脾肝三脏调理血证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9808,103);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9809,1,104,'论述',4,'分析','论述题：试述气与血关系失调（气滞血瘀、气虚血瘀、气随血脱）的机理及治疗。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9809,'论述','气为血之帅，血为气之母。（1）气滞血瘀：气机郁滞，血行不畅，见胸胁胀痛、刺痛固定，治以行气活血（血府逐瘀汤）；（2）气虚血瘀：气虚推动无力，血行瘀阻，见神疲乏力伴刺痛，治以补气活血（补阳还五汤）；（3）气随血脱：大失血时气随血脱，见面色苍白、大汗淋漓、脉微欲绝，治宜补气固脱（独参汤）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9809,104);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9810,1,106,'论述',4,'分析','论述题：试述瘀血形成的病因病机及临床表现特点。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9810,'论述','瘀血形成原因：（1）气滞血瘀；（2）气虚血瘀；（3）血寒凝滞；（4）血热互结；（5）外伤出血等离经之血。临床表现特点：（1）疼痛，刺痛固定不移、夜间加剧；（2）肿块，固定不移；（3）出血，血色紫暗或夹有血块；（4）面色黧黑、肌肤甲错、舌质紫暗或有瘀斑、脉涩。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9810,106);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9811,2,205,'论述',5,'分析','论述题：试述八纲辨证中表里寒热虚实的辨证关系（含寒热真假、虚实真假）。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9811,'论述','八纲之间相互联系、相互转化。（1）表里与寒热虚实相兼：表寒、表热、里寒、里热等。（2）寒热真假：真寒假热（阴盛格阳，身热反欲盖衣、面红如妆而四肢厥冷）、真热假寒（阳盛格阴，四肢厥冷而胸腹灼热、口渴喜冷）。（3）虚实真假：真实假虚（大实有羸状）、真虚假实（至虚有盛候），须四诊合参、脉症相参辨析。（4）表里、寒热、虚实之间可相互转化。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9811,205);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9812,2,206,'论述',5,'分析','论述题：试述肝的病理变化及其常见证型。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9812,'论述','肝为刚脏，体阴用阳，主疏泄、藏血。病理证型：（1）肝气郁结：情志抑郁、胁痛胀满、脉弦，治以疏肝解郁（柴胡疏肝散）；（2）肝火上炎：头胀头痛、目赤口苦、急躁易怒、脉弦数，治以清肝泻火（龙胆泻肝汤）；（3）肝阳上亢：眩晕头痛、面红目赤、急躁易怒、腰膝酸软，属本虚标实，治以平肝潜阳（天麻钩藤饮）；（4）肝风内动：热极生风、肝阳化风、血虚生风、阴虚动风等；（5）肝血虚：眩晕目涩、爪甲不荣、经少，治以养血柔肝（四物汤）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9812,206);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9813,3,320,'论述',4,'分析','论述题：试述中药炮制的目的。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9813,'论述','（1）降低或消除药物的毒性、烈性或副作用（如附子炮制减毒）；（2）改变或缓和药性（如生地黄凉血、熟地黄补血）；（3）增强药物疗效（如醋制延胡索增强止痛）；（4）改变或增强药物作用的部位和趋向（引药归经）；（5）便于制剂和贮藏；（6）矫臭矫味，便于服用。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9813,320);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9814,4,401,'论述',5,'分析','论述题：试述银翘散与桑菊饮的异同。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9814,'论述','相同：均为辛凉解表剂，治外感风热表证。不同：（1）组成：银翘散重用金银花、连翘，配荆芥、豆豉、薄荷等；桑菊饮以桑叶、菊花为主，配杏仁、桔梗。（2）功效侧重：银翘散辛凉透表、清热解毒力强，为''辛凉平剂''；桑菊饮宣肺止咳为主，为''辛凉轻剂''。（3）主治：银翘散治温病初起热毒偏盛之发热、咽痛；桑菊饮治风温初起咳嗽为主之证。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9814,401);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9815,4,406,'论述',5,'分析','论述题：试述补中益气汤的组成、功效、主治及配伍意义。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9815,'论述','组成：黄芪、人参、白术、炙甘草、当归、陈皮、升麻、柴胡。功效：补中益气、升阳举陷。主治：脾胃气虚证（食少体倦、少气懒言）、气虚下陷证（脱肛、久泻、脏器下垂）、气虚发热证（身热自汗）。配伍意义：重用黄芪为君补中益气、升阳固表；人参、白术、炙甘草为臣补气健脾；陈皮理气和胃、当归养血为佐；升麻、柴胡升阳举陷为使，引清阳上升。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9815,406);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9816,4,411,'论述',5,'分析','论述题：试述补阳还五汤的组方特点及应用注意。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9816,'论述','组成：黄芪（重用）、当归尾、赤芍、地龙、川芎、红花、桃仁。主治：中风之气虚血瘀证，半身不遂、口眼歪斜、舌苔白、脉缓。组方特点：重用黄芪（120g）为君，大补元气，使气旺以促血行；配当归尾、川芎、赤芍、桃仁、红花活血祛瘀，地龙通络。全方以补气为主、活血通络为辅，所谓''气旺则血行，血行则瘀祛''。应用注意：对中风后半身不遂以气虚血瘀为机者适用，阴虚阳亢、痰热壅盛者忌用；黄芪用量宜大。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9816,411);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9817,5,516,'论述',5,'分析','论述题：试述''面口合谷收''的理论依据及临床应用。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9817,'论述','合谷为手阳明大肠经原穴，大肠经循行''其支者，从缺盆上颈贯颊，入下齿中，还出挟口，交人中，左之右、右之左，上挟鼻孔''。手足阳明经相接，故合谷主治头面部疾患。临床用于治疗面瘫、齿痛、头痛、目赤肿痛、咽喉肿痛、鼻衄、口眼歪斜等。常配颊车、地仓治面瘫；配太冲组成四关穴，疏肝理气、通调气血。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9817,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9818,5,516,'论述',5,'分析','论述题：试述''肚腹三里留''的理论依据及临床意义。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9818,'论述','足三里为足阳明胃经合穴、胃之下合穴，''合治内腑''，故善治胃肠腑病。足阳明胃经循行于腹部，胃为水谷之海，故足三里能调理脾胃、补中益气、扶正培元。临床用于胃痛、呕吐、腹胀、泄泻、便秘等脾胃病证，并广泛用于虚劳羸瘦、气血亏虚诸证，为保健要穴（常灸足三里，胜吃老母鸡）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9818,516);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9819,6,602,'论述',5,'分析','论述题：试述胸痹与真心痛的区别及胸痹的辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9819,'论述','胸痹以胸部闷痛为主症，轻者偶发、短暂，重者持续不解；真心痛为胸痹重症，心痛剧烈、持续不解，伴汗出肢冷、面白唇青、脉微欲绝，属危候。胸痹辨证：心血瘀阻（血府逐瘀汤）、气滞心胸（柴胡疏肝散）、痰浊闭阻（瓜蒌薤白半夏汤）、寒凝心脉（枳实薤白桂枝汤）、气阴两虚（生脉散合人参养荣汤）、心肾阴虚（天王补心丹）、心肾阳虚（参附汤合右归饮）。治疗原则为补其不足、泻其有余、活血通络止痛。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9819,602);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9820,6,604,'论述',5,'分析','论述题：试述黄疸的辨证要点与治疗原则。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9820,'论述','辨证要点：（1）辨阴阳：阳黄黄色鲜明属湿热，阴黄黄色晦暗属寒湿；（2）辨湿热的偏重：热重于湿（茵陈蒿汤）、湿重于热（茵陈五苓散）；（3）辨病位及传变。治疗原则：利湿退黄为基本治则。阳黄清热利湿退黄；阴黄温中化湿退黄；急黄（疫毒炽盛）清热解毒、凉营开窍（犀角散），需中西医结合救治。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9820,604);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9821,6,605,'论述',5,'分析','论述题：试述水肿的辨证要点及阳水阴水的治法。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9821,'论述','水肿辨证要点：（1）辨阳水阴水：阳水起病急、多从头面先肿、肿势皮肤光亮，属实证；阴水起病缓、多从下肢先肿、肿势皮色晦暗，属虚证。（2）辨脏腑：病在肺、脾、肾。（3）辨邪正虚实。治疗：阳水以祛邪为主，风水相搏用越婢加术汤发汗、水湿浸渍用五皮饮利水、湿毒浸淫用麻黄连翘赤小豆汤；阴水以扶正为主，脾阳虚衰用实脾饮、肾阳衰微用济生肾气丸合真武汤。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9821,605);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9822,6,606,'论述',5,'分析','论述题：试述消渴的病机、辨证要点及治疗。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9822,'论述','病机：阴津亏损、燥热偏盛，以阴虚为本、燥热为标，病变脏腑在肺、胃、肾。辨证要点：（1）辨上、中、下三消；（2）辨本虚标实。治疗原则：清热润燥、养阴生津，同时注意益气。上消消渴方，中消玉女煎，下消六味地黄丸；兼见血瘀、痰浊、水湿者随证加减。并强调饮食调护、运动、情志调节。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9822,606);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9823,6,607,'论述',5,'分析','论述题：试述痹证与痿证的鉴别及痹证的辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9823,'论述','鉴别：痹证以肢体关节疼痛为主，因风寒湿热等邪闭阻经络，治以祛邪通络止痛；痿证以肢体痿软无力、肌肉萎缩为主，多无疼痛，由五脏亏损精血津液不足、筋脉失养所致，治以补益。痹证辨证：行痹（防风汤）祛风通络散寒；痛痹（乌头汤）散寒止痛；着痹（薏苡仁汤）除湿通络；热痹（白虎加桂枝汤）清热通络；尪痹（独活寄生汤）补肝肾益气血、祛风湿止痹痛。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9823,607);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9824,6,601,'论述',5,'分析','论述题：试述哮病发作期与缓解期的辨治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9824,'论述','哮病发作期：（1）冷哮：喉中哮鸣如水鸡声、咳痰清稀、形寒肢冷、苔白滑、脉弦紧，治以宣肺散寒、化痰平喘，方用射干麻黄汤或小青龙汤；（2）热哮：喘鸣气粗、痰黄稠、身热口渴、苔黄腻、脉滑数，治以清热宣肺、化痰定喘，方用定喘汤。缓解期：（1）肺脾气虚：补肺固卫、健脾化痰，玉屏风散合六君子汤；（2）肺肾两虚：补肺益肾、纳气平喘，生脉散合金匮肾气丸。发作期治标，缓解期治本，标本兼顾。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9824,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9825,6,601,'病案',3,'分析','病案分析：王某，男，45岁。恶寒重，发热轻，无汗，头痛身痛，鼻塞流清涕，咳嗽，痰白稀，舌苔薄白，脉浮紧。请辨证分型，确立治法，选方用药。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9825,'病案','辨证：风寒感冒（外感风寒表实证）。依据：恶寒重发热轻、无汗、头痛身痛、流清涕、苔薄白、脉浮紧，属风寒束表、肺气失宣。治法：辛温解表，宣肺散寒。代表方：荆防败毒散加减。药物：荆芥、防风、羌活、独活、柴胡、前胡、川芎、枳壳、茯苓、桔梗、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9825,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9826,6,601,'病案',3,'分析','病案分析：李某，女，30岁。咳嗽3天，咽痒即咳，痰少色白，鼻塞流涕，头痛，恶寒发热，舌苔薄白，脉浮。请辨证、立法、选方。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9826,'病案','辨证：外感咳嗽之风寒袭肺证。依据：咳嗽咽痒、痰白、兼表寒证（恶寒发热、鼻塞、脉浮）。治法：疏风散寒，宣肺止咳。代表方：三拗汤合止嗽散加减。药物：麻黄、杏仁、桔梗、紫菀、款冬花、白前、荆芥、陈皮、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9826,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9827,6,601,'病案',4,'分析','病案分析：张某，男，60岁。气喘20余年，遇寒加重。现症：喘促气短，动则喘甚，呼多吸少，气不得续，形瘦神疲，腰膝酸软，舌淡苔白，脉沉弱。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9827,'病案','辨证：喘证之肾虚不纳证（下虚上盛）。依据：久喘伤肾，动则喘甚、呼多吸少、气不得续，为肾不纳气；腰膝酸软、脉沉弱为肾虚之征。治法：补肾纳气。代表方：金匮肾气丸合参蛤散加减。药物：熟地黄、山药、山茱萸、茯苓、泽泻、牡丹皮、附子、肉桂、人参、蛤蚧、五味子。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9827,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9828,6,601,'病案',3,'分析','病案分析：陈某，女，38岁。心悸失眠半年，健忘多梦，面色萎黄，食少乏力，舌淡，脉细弱。请辨证分型、立法选方。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9828,'病案','辨证：心悸之心脾两虚证。依据：心悸健忘、食少乏力、面色萎黄、舌淡脉细弱，为心脾两虚、气血不足、心神失养。治法：补血养心，益气安神。代表方：归脾汤加减。药物：黄芪、党参、白术、当归、龙眼肉、茯神、酸枣仁、远志、木香、炙甘草、大枣。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9828,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9829,6,601,'病案',4,'分析','病案分析：刘某，男，58岁。胸痛反复发作2年，近日加重。胸痛如刺，固定不移，入夜尤甚，胸闷，舌质紫暗，有瘀斑，脉弦涩。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9829,'病案','辨证：胸痹之心血瘀阻证。依据：胸痛如刺、固定不移、入夜尤甚，舌紫暗有瘀斑、脉涩，为瘀血痹阻心脉。治法：活血化瘀，通脉止痛。代表方：血府逐瘀汤加减。药物：桃仁、红花、当归、生地、川芎、赤芍、牛膝、桔梗、柴胡、枳壳、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9829,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9830,6,601,'病案',4,'分析','病案分析：赵某，女，42岁。失眠3月余，入睡困难，多梦易醒，头晕目眩，心悸健忘，口苦咽干，舌红少苔，脉细数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9830,'病案','辨证：不寐之阴虚火旺证。依据：失眠多梦、心悸健忘、口苦咽干、舌红少苔、脉细数，为阴虚火旺、心肾不交、心神不宁。治法：滋阴降火，清心安神。代表方：天王补心丹或黄连阿胶汤加减。药物：生地黄、麦冬、玄参、天冬、丹参、当归、酸枣仁、柏子仁、远志、五味子、黄连、黄芩。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9830,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9831,6,601,'病案',4,'分析','病案分析：周某，男，52岁。头晕目眩3年，头胀痛，烦躁易怒，失眠多梦，口苦，面红目赤，舌红苔黄，脉弦数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9831,'病案','辨证：眩晕之肝阳上亢证。依据：眩晕头痛、烦躁易怒、口苦、面红目赤、脉弦数，为肝阳上亢、风阳上扰清窍。治法：平肝潜阳，清火息风。代表方：天麻钩藤饮加减。药物：天麻、钩藤、石决明、栀子、黄芩、牛膝、杜仲、益母草、桑寄生、夜交藤、茯神。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9831,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9832,6,601,'病案',3,'分析','病案分析：吴某，男，35岁。胃脘胀痛2月，连及两胁，遇情志不遂加重，嗳气频作，善太息，舌淡红苔薄白，脉弦。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9832,'病案','辨证：胃痛之肝气犯胃证。依据：胃脘胀痛连胁、与情志相关、嗳气太息、脉弦，为肝气郁结、横逆犯胃、胃失和降。治法：疏肝解郁，理气止痛。代表方：柴胡疏肝散加减。药物：柴胡、陈皮、川芎、香附、枳壳、芍药、炙甘草、延胡索、佛手。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9832,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9833,6,601,'病案',3,'分析','病案分析：郑某，女，28岁。泄泻3天，大便清稀如水样，腹痛肠鸣，脘闷食少，恶寒发热，鼻塞，舌苔白腻，脉濡缓。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9833,'病案','辨证：泄泻之寒湿困脾证（兼表证）。依据：泄泻清稀如水、肠鸣、脘闷，苔白腻，属寒湿内盛；恶寒发热、鼻塞为外感风寒。治法：解表散寒，芳香化湿。代表方：藿香正气散加减。药物：藿香、紫苏、白芷、半夏、陈皮、白术、茯苓、厚朴、桔梗、大腹皮、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9833,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9834,6,601,'病案',4,'分析','病案分析：钱某，男，40岁。下痢2天，腹痛，里急后重，下痢赤白脓血，肛门灼热，小便短赤，舌苔黄腻，脉滑数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9834,'病案','辨证：痢疾之湿热痢。依据：下痢赤白脓血、里急后重、肛门灼热、苔黄腻、脉滑数，为湿热蕴结肠腑、气血壅滞。治法：清肠化湿，调气行血。代表方：芍药汤加减。药物：芍药、当归、黄连、黄芩、大黄、木香、槟榔、肉桂、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9834,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9835,6,601,'病案',3,'分析','病案分析：孙某，女，32岁。大便秘结5天，腹胀腹痛，嗳气频作，胸胁痞满，舌苔薄腻，脉弦。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9835,'病案','辨证：便秘之气秘。依据：便秘、腹胀、嗳气、胸胁痞满、脉弦，为气机郁滞、大肠传导失职。治法：顺气导滞。代表方：六磨汤加减。药物：木香、乌药、沉香、大黄、槟榔、枳实。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9835,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9836,6,601,'病案',3,'分析','病案分析：冯某，男，48岁。右胁胀痛3月，走窜不定，疼痛每因情志变动而增减，胸闷嗳气，纳少，舌苔薄白，脉弦。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9836,'病案','辨证：胁痛之肝气郁结证。依据：胁肋胀痛、走窜不定、随情志增减、脉弦，为肝气郁结、气机不畅。治法：疏肝理气。代表方：柴胡疏肝散加减。药物：柴胡、陈皮、川芎、香附、枳壳、芍药、炙甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9836,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9837,6,601,'病案',4,'分析','病案分析：高某，男，36岁。身目俱黄，黄色鲜明如橘色，发热口渴，恶心呕吐，腹胀，小便短少黄赤，大便秘结，舌苔黄腻，脉弦数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9837,'病案','辨证：黄疸之阳黄（热重于湿）。依据：身目俱黄、黄色鲜明、发热口渴、大便秘结、苔黄腻、脉弦数，为湿热熏蒸肝胆、胆汁泛溢。治法：清热利湿，佐以通腑。代表方：茵陈蒿汤加减。药物：茵陈、栀子、大黄，酌加茯苓、猪苓、车前子等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9837,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9838,6,601,'病案',4,'分析','病案分析：王某，女，26岁。眼睑浮肿2天，继则全身浮肿，恶风发热，咽喉肿痛，小便不利，舌苔薄白，脉浮数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9838,'病案','辨证：水肿之风水相搏证（阳水）。依据：起病急、眼睑浮肿迅速及全身、恶风发热、咽喉肿痛、脉浮数，为风邪袭表、肺失通调、水泛肌肤。治法：疏风清热，宣肺行水。代表方：越婢加术汤加减。药物：麻黄、石膏、白术、生姜、大枣、甘草，酌加金银花、连翘、板蓝根。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9838,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9839,6,601,'病案',3,'分析','病案分析：李某，男，32岁。小便频数短涩，灼热刺痛，尿色黄赤，小腹拘急胀痛，口苦，舌红苔黄腻，脉数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9839,'病案','辨证：淋证之热淋。依据：小便频数短涩、灼热刺痛、尿色黄赤、苔黄腻、脉数，为湿热蕴结下焦、膀胱气化不利。治法：清热利湿通淋。代表方：八正散加减。药物：车前子、瞿麦、萹蓄、滑石、山栀子、木通、大黄、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9839,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9840,6,601,'病案',4,'分析','病案分析：张某，男，50岁。多饮多食多尿2年，形体消瘦，腰膝酸软，头晕耳鸣，失眠，舌红少苔，脉细数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9840,'病案','辨证：消渴之下消（肾阴亏虚）。依据：多饮多食多尿、形体消瘦、腰膝酸软、舌红少苔、脉细数，为肾阴亏虚、虚火内炽、固摄失权。治法：滋阴固肾。代表方：六味地黄丸加减。药物：熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓，加枸杞子、黄精、益智仁等。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9840,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9841,6,601,'病案',4,'分析','病案分析：陈某，男，38岁。反复鼻衄、齿衄半年，神疲乏力，面色苍白，头晕心悸，舌淡，脉细弱。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9841,'病案','辨证：血证（鼻衄、齿衄）之气虚不摄证。依据：反复出血、神疲乏力、面色苍白、舌淡脉细弱，为脾气亏虚、统摄无权、血溢脉外。治法：益气摄血。代表方：归脾汤加减。药物：黄芪、党参、白术、当归、龙眼肉、茯神、酸枣仁、远志、木香、炙甘草、大枣。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9841,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9842,6,601,'病案',4,'分析','病案分析：刘某，女，45岁。双膝关节冷痛重着2年，屈伸不利，遇寒加重，得温痛减，舌苔白腻，脉弦紧。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9842,'病案','辨证：痹证之痛痹（寒湿偏盛）。依据：关节冷痛、遇寒加重、得温痛减、苔白腻、脉弦紧，为寒湿闭阻经络、气血运行不畅。治法：散寒止痛，祛风除湿。代表方：乌头汤加减。药物：制川乌、麻黄、芍药、黄芪、甘草，酌加威灵仙、独活、秦艽。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9842,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9843,6,601,'病案',5,'分析','病案分析：王某，男，40岁。双下肢痿软无力半年，逐渐加重，肌肉萎缩，腰脊酸软，头晕耳鸣，舌红少苔，脉细数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9843,'病案','辨证：痿证之肝肾亏损证。依据：下肢痿软、肌肉萎缩、腰脊酸软、头晕耳鸣、舌红少苔、脉细数，为肝肾亏虚、精血不足、筋脉失养。治法：补益肝肾，滋阴清热。代表方：虎潜丸加减。药物：熟地黄、龟板、黄柏、知母、白芍、锁阳、陈皮、干姜、虎骨（现用狗骨代）。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9843,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9844,6,601,'病案',4,'分析','病案分析：孙某，男，42岁。头痛且胀，面红目赤，心烦易怒，夜寐不宁，口苦胁痛，舌红苔黄，脉弦数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9844,'病案','辨证：头痛之肝阳上亢证。依据：头痛且胀、面红目赤、心烦易怒、口苦、脉弦数，为肝阳上亢、风阳上扰清窍。治法：平肝潜阳息风。代表方：天麻钩藤饮加减。药物：天麻、钩藤、石决明、栀子、黄芩、牛膝、杜仲、益母草、桑寄生、夜交藤、茯神。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9844,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9845,6,601,'病案',4,'分析','病案分析：赵某，男，55岁。腰痛绵绵，酸软无力，劳累后加重，休息后减轻，手足不温，舌淡，脉沉细。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9845,'病案','辨证：腰痛之肾虚腰痛（肾阳虚）。依据：腰痛绵绵、酸软无力、劳则加重、手足不温、脉沉细，为肾阳不足、腰府失养。治法：补肾壮阳，温煦经脉。代表方：右归丸加减。药物：熟地黄、山药、山茱萸、枸杞子、鹿角胶、菟丝子、杜仲、肉桂、当归、附子。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9845,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9846,6,601,'病案',3,'分析','病案分析：李某，女，35岁。精神抑郁，情绪不宁，胸胁胀满，善太息，不思饮食，月经不调，舌淡红苔薄白，脉弦。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9846,'病案','辨证：郁证之肝气郁结证。依据：精神抑郁、胸胁胀满、善太息、脉弦，为肝失疏泄、气机郁滞。治法：疏肝解郁，理气畅中。代表方：柴胡疏肝散或越鞠丸加减。药物：柴胡、陈皮、川芎、香附、枳壳、芍药、炙甘草、郁金、合欢皮。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9846,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9847,6,601,'病案',3,'分析','病案分析：刘某，女，36岁。发热重，微恶风寒，汗出不畅，头痛，咽痛，咳嗽痰黄，口渴，舌尖红，苔薄黄，脉浮数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9847,'病案','辨证：风热感冒。依据：发热重微恶寒、咽痛、痰黄、口渴、舌边尖红、苔薄黄、脉浮数，为风热犯表、热邪伤津。治法：辛凉解表，清热解毒。代表方：银翘散加减。药物：金银花、连翘、桔梗、薄荷、牛蒡子、竹叶、荆芥穗、淡豆豉、甘草、芦根，加板蓝根、蒲公英。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9847,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9848,6,601,'病案',4,'分析','病案分析：张某，男，55岁。咳嗽反复发作5年，咳声重浊，痰多黏腻，色白，胸闷，脘痞，食少，舌苔白腻，脉濡滑。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9848,'病案','辨证：咳嗽之痰湿蕴肺证。依据：反复咳嗽、痰多黏腻色白、胸闷脘痞、苔白腻、脉濡滑，为脾湿生痰、上渍于肺、肺失宣降。治法：燥湿化痰，理气止咳。代表方：二陈汤合三子养亲汤加减。药物：半夏、陈皮、茯苓、甘草、紫苏子、白芥子、莱菔子，加苍术、厚朴。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9848,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9849,6,601,'病案',5,'分析','病案分析：王某，男，20岁。反复发作性喘息5年，近日因受凉复发。喉中痰鸣如水鸡声，呼吸急促，胸膈满闷，咳痰清稀，形寒怕冷，舌苔白滑，脉弦紧。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9849,'病案','辨证：哮病发作期之冷哮证。依据：喉中痰鸣如水鸡声、呼吸急促、痰清稀、形寒怕冷、苔白滑、脉弦紧，为寒痰伏肺、遇寒触发、气道挛急。治法：宣肺散寒，化痰平喘。代表方：射干麻黄汤或小青龙汤加减。药物：射干、麻黄、细辛、半夏、生姜、紫菀、款冬花、五味子、大枣。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9849,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9850,6,601,'病案',4,'分析','病案分析：孙某，女，50岁。心悸不安，胸闷气短，活动后加重，面色苍白，形寒肢冷，舌淡胖，苔白，脉沉细弱。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9850,'病案','辨证：心悸之心阳不振证。依据：心悸胸闷、形寒肢冷、面色苍白、舌淡胖、脉沉细弱，为心阳虚衰、温养失职、鼓动无力。治法：温补心阳，安神定悸。代表方：桂枝甘草龙骨牡蛎汤合参附汤加减。药物：桂枝、炙甘草、龙骨、牡蛎、人参、附子。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9850,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9851,6,601,'病案',3,'分析','病案分析：赵某，男，60岁。神疲乏力，气短懒言，自汗，纳少便溏，腹胀，面色萎黄，舌淡苔白，脉虚弱。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9851,'病案','辨证：虚劳之脾气虚证。依据：神疲乏力、气短自汗、纳少便溏、面色萎黄、脉虚弱，为脾虚运化失职、气血生化不足。治法：健脾益气。代表方：四君子汤或参苓白术散加减。药物：人参、白术、茯苓、甘草、山药、莲子、薏苡仁。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9851,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9852,6,601,'病案',5,'分析','病案分析：陈某，男，48岁。全身水肿反复发作1年，腰以下为甚，按之凹陷不易恢复，脘腹胀闷，纳少便溏，小便短少，畏寒肢冷，舌淡胖苔白滑，脉沉缓。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9852,'病案','辨证：水肿之阴水（脾阳虚衰证）。依据：水肿反复、腰以下为甚、按之凹陷不易恢复、脘闷纳少、畏寒肢冷、舌淡胖苔白滑、脉沉缓，为脾阳不振、运化无权、水湿内停。治法：温运脾阳，以利水湿。代表方：实脾饮加减。药物：附子、干姜、白术、厚朴、木香、草果、槟榔、茯苓、木瓜、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9852,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9853,6,601,'病案',5,'分析','病案分析：钱某，男，52岁。腹大胀满，按之如囊裹水，胸脘胀闷，得热则舒，精神困倦，怯寒懒动，小便少，大便溏，舌苔白腻，脉缓。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9853,'病案','辨证：鼓胀之水湿困脾证。依据：腹大如囊裹水、脘闷得热则舒、怯寒懒动、小便少、苔白腻、脉缓，为脾阳不振、水湿内停。治法：温中健脾，行气利水。代表方：实脾饮加减。药物：附子、干姜、白术、厚朴、木香、草果、槟榔、茯苓、木瓜、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9853,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9854,6,601,'病案',5,'分析','病案分析：李某，男，30岁。吐血鲜红，夹有食物残渣，口臭，便秘，胃脘灼痛，舌红苔黄，脉滑数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9854,'病案','辨证：血证（吐血）之胃热壅盛证。依据：吐血鲜红、胃脘灼痛、口臭便秘、舌红苔黄、脉滑数，为胃火炽盛、灼伤血络、迫血妄行。治法：清胃泻火，化瘀止血。代表方：泻心汤合十灰散加减。药物：大黄、黄连、黄芩、十灰散。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9854,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9855,6,601,'病案',4,'分析','病案分析：周某，男，40岁。头晕目眩，视物旋转，头重如裹，胸闷恶心，呕吐痰涎，食少多寐，舌苔白腻，脉濡滑。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9855,'病案','辨证：眩晕之痰湿中阻证。依据：头晕头重如裹、胸闷恶心、呕吐痰涎、苔白腻、脉濡滑，为痰湿中阻、清阳不升、浊阴不降。治法：化痰祛湿，健脾和胃。代表方：半夏白术天麻汤加减。药物：半夏、天麻、白术、茯苓、橘红、甘草、生姜、大枣。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9855,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9856,6,601,'病案',4,'分析','病案分析：王某，女，36岁。头痛而空，眩晕，耳鸣，腰膝酸软，神疲乏力，舌红少苔，脉细无力。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9856,'病案','辨证：头痛之肾虚头痛。依据：头痛而空、眩晕耳鸣、腰膝酸软、神疲乏力、舌红少苔、脉细无力，为肾精亏虚、髓海不足、脑窍失养。治法：养阴补肾，填精生髓。代表方：大补元煎加减。药物：人参、熟地黄、山药、杜仲、当归、枸杞子、山茱萸、炙甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9856,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9857,6,601,'病案',5,'分析','病案分析：孙某，女，62岁。胸闷隐痛，时作时止，气短乏力，心悸盗汗，口干，舌红少苔，脉细数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9857,'病案','辨证：胸痹之气阴两虚证。依据：胸闷隐痛、气短乏力、心悸盗汗、口干、舌红少苔、脉细数，为气阴两虚、心脉失养。治法：益气养阴，活血通脉。代表方：生脉散合人参养荣汤加减。药物：人参、麦冬、五味子、黄芪、当归、白芍、熟地黄、丹参、郁金。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9857,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9858,6,601,'病案',4,'分析','病案分析：王某，女，48岁。口渴多饮，尿频量多，多食易饥，形体消瘦，大便干燥，舌红苔黄，脉滑实有力。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9858,'病案','辨证：消渴之中消（胃热炽盛证）。依据：多食易饥、口渴多饮、尿频量多、形体消瘦、大便干燥、舌红苔黄、脉滑实，为胃火炽盛、消谷耗津。治法：清胃泻火，养阴增液。代表方：玉女煎加减。药物：石膏、熟地黄、麦冬、知母、牛膝，加黄连、栀子。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9858,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9859,6,601,'病案',4,'分析','病案分析：陈某，男，65岁。泄泻反复发作3年，每于黎明前脐腹作痛，肠鸣即泻，完谷不化，形寒肢冷，腰膝酸软，舌淡苔白，脉沉细。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9859,'病案','辨证：泄泻之肾阳虚衰证（五更泄泻）。依据：黎明泄泻、完谷不化、形寒肢冷、腰膝酸软、脉沉细，为命门火衰、脾失温煦、运化失职。治法：温肾健脾，固涩止泻。代表方：四神丸加减。药物：补骨脂、肉豆蔻、吴茱萸、五味子、生姜、大枣，加附子、炮姜。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9859,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9860,6,601,'病案',4,'分析','病案分析：刘某，女，32岁。呕吐吞酸，嗳气频繁，胸胁胀满，每因情志不遂加重，舌边红，苔薄腻，脉弦。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9860,'病案','辨证：呕吐之肝气犯胃证。依据：呕吐吞酸、嗳气频作、胸胁胀满、随情志加重、脉弦，为肝气郁结、横逆犯胃、胃气上逆。治法：疏肝理气，和胃降逆。代表方：四逆散合半夏厚朴汤加减。药物：柴胡、白芍、枳壳、甘草、半夏、厚朴、茯苓、生姜、紫苏叶，加左金丸。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9860,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9861,6,601,'病案',4,'分析','病案分析：张某，女，70岁。大便艰涩，排出困难，四肢不温，腹中冷痛，腰膝酸软，小便清长，舌淡苔白，脉沉迟。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9861,'病案','辨证：便秘之冷秘（阳虚秘）。依据：大便艰涩、四肢不温、腹中冷痛、小便清长、脉沉迟，为阳气虚衰、阴寒凝滞、传导无力。治法：温阳散寒通便。代表方：济川煎加减（温肾益精，润肠通便）。药物：肉苁蓉、牛膝、当归、泽泻、升麻、枳壳。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9861,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9862,6,601,'病案',5,'分析','病案分析：王某，男，60岁。突然昏仆，不省人事，牙关紧闭，口噤不开，两手握固，肢体强痉，面赤身热，气粗口臭，苔黄腻，脉弦滑数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9862,'病案','辨证：中风之中脏腑（阳闭证）。依据：昏仆不省人事、牙关紧闭、两手握固属闭证；面赤身热、气粗口臭、苔黄腻、脉弦滑数为痰热内闭清窍。治法：清肝息风，豁痰开窍。代表方：羚角钩藤汤合安宫牛黄丸（或至宝丹）加减。药物：羚羊角、钩藤、桑叶、菊花、川贝母、竹茹、茯神、白芍、生地黄、甘草，送服安宫牛黄丸。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9862,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9863,6,601,'病案',3,'分析','病案分析：李某，女，50岁。关节疼痛游走不定，屈伸不利，恶风发热，舌苔薄白，脉浮。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9863,'病案','辨证：痹证之行痹（风邪偏盛）。依据：关节疼痛游走不定（风性善行数变）、恶风发热、脉浮。治法：祛风通络，散寒除湿。代表方：防风汤加减。药物：防风、麻黄、秦艽、当归、肉桂、葛根、茯苓、甘草、生姜、大枣。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9863,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9864,6,601,'病案',3,'分析','病案分析：陈某，男，50岁。腰膝酸软，头晕耳鸣，失眠多梦，遗精，舌红少津，脉细数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9864,'病案','辨证：虚劳之肾阴虚证。依据：腰膝酸软、头晕耳鸣、失眠遗精、舌红少津、脉细数，为肾阴亏虚、阴虚火旺、精关不固。治法：滋补肾阴。代表方：六味地黄丸加减。药物：熟地黄、山茱萸、山药、泽泻、牡丹皮、茯苓，加知母、黄柏、五味子。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9864,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9865,6,601,'病案',4,'分析','病案分析：赵某，男，48岁。失眠多梦，胸闷脘痞，头重目眩，痰多口苦，心烦，舌苔黄腻，脉滑数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9865,'病案','辨证：不寐之痰热内扰证。依据：失眠多梦、胸闷脘痞、头重目眩、痰多口苦、苔黄腻、脉滑数，为痰热内蕴、扰乱心神。治法：清化痰热，和中安神。代表方：黄连温胆汤加减。药物：黄连、半夏、竹茹、枳实、陈皮、茯苓、甘草、生姜、大枣，加珍珠母、远志。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9865,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9866,6,601,'病案',5,'分析','病案分析：李某，男，35岁。咳嗽，胸痛，咯吐大量腥臭脓痰，壮热烦渴，舌红苔黄腻，脉滑数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9866,'病案','辨证：肺痈之成痈期（或溃脓期）。依据：咯吐腥臭脓痰、胸痛、壮热烦渴、苔黄腻、脉滑数，为热毒蕴肺、血败肉腐成脓。治法：清肺解毒，化瘀消痈（溃脓期排脓解毒）。代表方：苇茎汤合如金解毒散加减。药物：苇茎、薏苡仁、冬瓜仁、桃仁、桔梗、贝母、金银花、鱼腥草、甘草。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9866,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9867,6,601,'病案',5,'分析','病案分析：王某，男，55岁。下痢时发时止2年，迁延不愈，腹部隐痛，食少神疲，畏寒肢冷，舌淡苔白腻，脉虚细。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9867,'病案','辨证：痢疾之虚寒痢（或休息痢）。依据：下痢反复发作、腹部隐痛、食少神疲、畏寒肢冷、舌淡苔白腻、脉虚细，为脾肾阳虚、寒湿留滞、肠络受损。治法：温补脾肾，收涩固脱。代表方：真人养脏汤加减。药物：人参、当归、白术、肉豆蔻、肉桂、甘草、白芍、木香、诃子、罂粟壳。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9867,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9868,6,601,'病案',5,'分析','病案分析：张某，男，30岁。眼睑浮肿，延及全身，身发疮痍，甚则溃烂，恶风发热，小便不利，舌红苔黄腻，脉浮数。请辨证论治。',20.0,1,now(),now());
INSERT INTO question_answer(question_id, answer_type, answer_text) VALUES (9868,'病案','辨证：水肿之湿毒浸淫证。依据：眼睑浮肿及全身、身发疮痍、恶风发热、小便不利、苔黄腻、脉浮数，为疮毒内归、脾肺失调、水湿内停。治法：宣肺解毒，利湿消肿。代表方：麻黄连翘赤小豆汤合五味消毒饮加减。药物：麻黄、连翘、赤小豆、杏仁、桑白皮、生姜、大枣、甘草，加银花、野菊花、蒲公英。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9868,601);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9869,1,101,'A',2,'记忆','阴阳学说中，阴阳双方具有相互依存、相互为用的关系，称为阴阳的',1.0,1,now(),now());
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9869,'A','对立制约',0);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9869,'B','互根互用',1);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9869,'C','消长平衡',0);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9869,'D','相互转化',0);
INSERT INTO question_analysis(question_id, analysis_text) VALUES (9869,'阴阳互根互用指阴阳双方相互依存、相互为用，任何一方不能脱离另一方而单独存在。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9869,101);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9870,1,101,'A',2,'记忆','阴和阳在一个统一体中的对比、消长变化，反映了阴阳的',1.0,1,now(),now());
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9870,'A','互根互用',0);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9870,'B','对立制约',0);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9870,'C','消长平衡',1);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9870,'D','相互转化',0);
INSERT INTO question_analysis(question_id, analysis_text) VALUES (9870,'阴阳消长是阴阳在对立制约和互根互用基础上的量变过程。');
INSERT INTO question_knowledge(question_id, knowledge_point_id) VALUES (9870,101);
INSERT INTO question(id, subject_id, knowledge_point_id, qtype, difficulty, cognitive_level, stem, score, status, created_at, updated_at) VALUES (9871,1,101,'A',2,'记忆','寒者热之、热者寒之，是根据阴阳的何种关系确立的治疗原则',1.0,1,now(),now());
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9871,'A','对立制约',1);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9871,'B','互根互用',0);
INSERT INTO question_option(question_id, option_key, option_text, is_correct) VALUES (9871,'C','消长平衡',0);
